const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function safe(value, fallback = null) {
  return value === undefined || value === null || value === "" ? fallback : value;
}

function countBy(records, getter) {
  const counts = {};
  for (const record of records) {
    const key = safe(getter(record), "unknown");
    counts[key] = (counts[key] || 0) + 1;
  }
  return counts;
}

function makeDigestId(eventId) {
  const base = eventId || "unknown_event";
  const suffix = Date.now().toString(36);
  return `digest_${base}_${suffix}`.replace(/[^a-zA-Z0-9_]/g, "_");
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-J",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        digest: null,
        notification_payload: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-J will not build digest when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "build_digest") {
  return fail({
    code: "DIGEST_NOT_REQUESTED",
    message: "source.next_action is not build_digest.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!Array.isArray(source.records)) {
  return fail({
    code: "MISSING_RECORDS_ARRAY",
    message: "input.records must be an array."
  });
}

if (!config.digest_type) {
  return fail({
    code: "MISSING_DIGEST_TYPE",
    message: "config.digest_type is required."
  });
}

if (!config.recipient_email) {
  return fail({
    code: "MISSING_RECIPIENT_EMAIL",
    message: "config.recipient_email is required."
  });
}

const records = source.records;
const maxDetailItems = Number(config.max_detail_items ?? 10);
const createdAt = nowIso();
const digestId = makeDigestId(source.event_id);

const byRecordType = countBy(records, r => r.record_type);
const byEventType = countBy(records, r => r.event_type);
const byStatus = countBy(records, r => r.current_status || r.status);
const byOwner = countBy(records, r => r.owner || r.owner_email || r.reviewer_email);
const byPriority = countBy(records, r => r.priority || r.severity);

const failedCount = records.filter(r =>
  r.current_status === "failed" ||
  r.status === "failed" ||
  r.status === "logged" ||
  r.record_type === "error_log"
).length;

const pendingApprovalCount = records.filter(r =>
  r.current_status === "pending_approval" ||
  r.approval_status === "pending" ||
  r.status === "pending" ||
  r.record_type === "approval"
).length;

const manualReviewCount = records.filter(r =>
  r.current_status === "manual_review" ||
  r.next_action === "manual_review" ||
  r.retry_status === "pending_manual_review"
).length;

const completedCount = records.filter(r =>
  r.current_status === "completed" ||
  r.status === "completed"
).length;

const attentionItems = records.filter(r =>
  r.current_status === "failed" ||
  r.current_status === "manual_review" ||
  r.current_status === "pending_approval" ||
  r.status === "logged" ||
  r.status === "pending" ||
  r.record_type === "error_log" ||
  r.record_type === "approval" ||
  r.next_action === "manual_review" ||
  r.retry_status === "pending_manual_review"
).slice(0, maxDetailItems);

const detailLines = attentionItems.map((r, index) => {
  const label = r.event_id || r.approval_id || r.error_id || `item_${index + 1}`;
  const status = r.current_status || r.status || "unknown";
  const reason = r.error_code || r.source_error_code || r.approval_type || r.next_action || r.current_stage || "";
  return `${index + 1}. ${label} | ${r.event_type || "-"} | ${status}${reason ? " | " + reason : ""}`;
});

const title = config.digest_title || `${config.digest_type} digest`;

const text = [
  `${title}`,
  ``,
  `Digest ID: ${digestId}`,
  `Type: ${config.digest_type}`,
  `Total records: ${records.length}`,
  `Completed: ${completedCount}`,
  `Failed/errors: ${failedCount}`,
  `Pending approvals: ${pendingApprovalCount}`,
  `Manual review / retry: ${manualReviewCount}`,
  ``,
  `Counts by status: ${JSON.stringify(byStatus)}`,
  `Counts by event type: ${JSON.stringify(byEventType)}`,
  ``,
  config.include_record_details ? `Attention items:` : null,
  config.include_record_details ? (detailLines.length ? detailLines.join("\n") : "None") : null
].filter(line => line !== null).join("\n");

const digest = {
  digest_id: digestId,
  digest_type: config.digest_type,
  digest_title: title,
  total_records: records.length,
  counts: {
    completed: completedCount,
    failed: failedCount,
    pending_approval: pendingApprovalCount,
    manual_review: manualReviewCount,
    by_record_type: byRecordType,
    by_event_type: byEventType,
    by_status: byStatus,
    by_owner: byOwner,
    by_priority: byPriority
  },
  attention_items: attentionItems,
  summary_text: text,
  owner: config.owner || "unassigned",
  created_at: createdAt
};

return [
  {
    json: {
      success: true,
      component_id: "C2-J",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      digest,
      notification_payload: {
        channel: "email",
        to: config.recipient_email,
        subject: `${title} — ${records.length} records`,
        text
      },
      source_result: source,
      error: null,
      next_action: config.default_next_action || "send_digest_notification"
    }
  }
];
